        const g = ctx.createRadialGradient(x, y, 0, x, y, len * 1.4);
        g.addColorStop(0, 'rgba(255,250,210,1)'); g.addColorStop(.3, 'rgba(255,190,60,.85)'); g.addColorStop(.7, 'rgba(255,90,30,.35)'); g.addColorStop(1, 'rgba(255,60,20,0)');
