        const k = f.fx / CAMH, y = f.hy + f.fy + (state === 'run' ? Math.sin(time * 26) * .6 : 0);
        const im = pic(ART.cars[mycar]), cw = CARW * 1.12 * k;
        ctx.save(); ctx.translate(W / 2, y); ctx.rotate((LANE_X[lane] - px) * .35);
        if (im) { shadow(0, 0, cw); stand(im, 0, cw * .02, cw); } else carRear(0, 0, CARW * 1.05 * k, C.car);
